WITH parsed AS (SELECT id, service, log_ts, level, status_code, payload_json, context, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT service, CASE WHEN status_code >= 460 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, APPROX_PERCENTILE(status_code, 0.5) AS status_code_p50, COUNT_IF(level = 'DEBUG') AS debug_events, BIT_OR(status_code) AS status_code_bit_or, PERCENT_RANK() OVER (PARTITION BY service ORDER BY BIT_OR(status_code) DESC) AS status_code_bit_or_percent_rank FROM parsed GROUP BY service, status_code_tier ORDER BY debug_events DESC;
